// The app icon (Stride N) comes in five colour schemes. Which one a phone
// uses is a per-device choice, kept in the `nutriscore_icon` cookie so the
// server can put the right <link rel="apple-touch-icon">, favicon and
// manifest icons in the page (app/layout.js, app/api/manifest/route.js).
// The PNGs live in public/icons/ and are generated by
// scripts/icons/render-icons.mjs — re-run it after changing the design.
export const ICON_COOKIE = "nutriscore_icon";
export const DEFAULT_ICON = "duo";

// `bg` is the icon's background colour (manifest background/theme colour).
export const APP_ICONS = [
  { key: "duo", name: "Duo", bg: "#141325" },
  { key: "bay", name: "Tallinn Bay", bg: "#072a40" },
  { key: "sunrise", name: "Race Sunrise", bg: "#2e0f3a" },
  { key: "nordic", name: "Nordic Day", bg: "#f4f7fb" },
  { key: "gold", name: "Black & Gold", bg: "#0b0b0d" }
];

export function iconKey(value) {
  return APP_ICONS.some((i) => i.key === value) ? value : DEFAULT_ICON;
}

// Called from the Colour panel: remembers the choice for a year and swaps the
// live <link> tags, so the tab icon changes at once and Android picks up the
// new manifest.
export function setAppIcon(key) {
  key = iconKey(key);
  document.cookie = ICON_COOKIE + "=" + key + "; path=/; max-age=31536000; samesite=lax";
  const set = (sel, href) => document.querySelectorAll(sel).forEach((el) => el.setAttribute("href", href));
  set('link[rel="icon"]', iconPath(key, 32));
  set('link[rel="apple-touch-icon"]', iconPath(key, 180));
  set('link[rel="manifest"]', "/api/manifest?icon=" + key);
}

export function currentAppIcon() {
  const m = typeof document !== "undefined" && document.cookie.match(new RegExp("(?:^|; )" + ICON_COOKIE + "=([^;]*)"));
  return iconKey(m ? m[1] : null);
}

// size: 32 | 180 | 192 | 512 | "512-maskable"
export function iconPath(key, size) {
  return "/icons/stride-" + iconKey(key) + "-" + size + ".png";
}
